def solve(data):
    fields = data['fields'].copy()
    log = data['log']
    end = len(log)
    for _ in range(data['steps']):
        if end == 0:
            break
        last = log[end - 1]
        start = end - 1
        while start > 0:
            prev = log[start - 1]
            if (prev['field'], prev['gesture']) != (last['field'], last['gesture']):
                break
            start -= 1
        fields[last['field']] = last['before']
        end = start
    return fields

